{"command":"python3 << 'EOF'
import csv

# Check RFC 4180 compliance for stops.csv
with open('outputs/t05_clean_stops.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)
    print(f"Header: {header}")

    for i, row in enumerate(reader):
        # Check if row has same number of fields as header
        if len(row) != len(header):
            print(f"Row {i+2} has {len(row)} fields, expected {len(header)}")
        # Check for unquoted fields with special chars
        for j, field in enumerate(row):
            if ',' in field or '"' in field or '\n' in field:
                if not field.startswith('"') or not field.endswith('"'):
                    print(f"Row {i+2}, field {j}: {repr(field)} is not quoted")
        if i > 5:
            break
    print("Stops CSV check complete")

# Check RFC 4180 compliance for stop_times.csv
with open('outputs/t05_clean_stop_times.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)
    print(f"Header: {header}")

    for i, row in enumerate(reader):
        # Check if row has same number of fields as header
        if len(row) != len(header):
            print(f"Row {i+2} has {len(row)} fields, expected {len(header)}")
        if i > 5:
            break
    print("Stop_times CSV check complete")
EOF"}
